<?php require_once __DIR__.'/../config/db.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){$nombre=trim($_POST['nombre']);$usuario=trim($_POST['usuario']);$password=password_hash($_POST['password'],PASSWORD_DEFAULT);$rol=$_POST['rol'];$estado=$_POST['estado'];$s=$pdo->prepare('INSERT INTO usuarios(nombre,usuario,password,rol,estado) VALUES(?,?,?,?,?)');$s->execute([$nombre,$usuario,$password,$rol,$estado]);header('Location: usuarios.php');exit;}$rows=$pdo->query('SELECT id_usuario,nombre,usuario,rol,estado FROM usuarios ORDER BY nombre')->fetchAll();$title='Usuarios';require 'header.php';?><h2>Usuarios</h2><div class="card mb-4"><div class="card-body"><form method="post" class="row g-2"><div class="col-md-3"><input class="form-control" name="nombre" placeholder="Nombre" required></div><div class="col-md-2"><input class="form-control" name="usuario" placeholder="Usuario" required></div><div class="col-md-2"><input class="form-control" type="password" name="password" placeholder="Contraseña" required></div><div class="col-md-2"><select class="form-select" name="rol"><option value="administrador">Administrador</option><option value="empleado">Empleado</option></select></div><div class="col-md-2"><select class="form-select" name="estado"><option value="activo">Activo</option><option value="inactivo">Inactivo</option></select></div><div class="col-md-1"><button class="btn btn-primary">Crear</button></div></form></div></div><div class="card"><div class="card-body"><table class="table"><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['usuario'])?></td><td><?=e($r['rol'])?></td><td><?=e($r['estado'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'footer.php';
